<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$users=load_json('users.json',[]);$error='';$message='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['action'])){require_csrf();$id=sanitize($_POST['id']??'');$action=sanitize($_POST['action']??'');if($id&&in_array($action,['activate','deactivate','delete'],true)){if($action==='delete'&&count(array_filter($users,fn($u)=>is_array($u)&&($u['role']??'')==='admin'))<=1){$error='The final administrator account cannot be deleted.';}elseif($action==='delete'){if(delete_json_item('users.json',fn($u)=>is_array($u)&&($u['id']??'')===$id)){$message='User deleted.';}else{$error='The user could not be deleted.';}}else{$updated=update_json('users.json',fn($list)=>array_map(fn($u)=>is_array($u)&&($u['id']??'')===$id?array_merge($u,['active'=>$action==='activate']):$u,$list));if($updated){$message=$action==='activate'?'User activated.':'User deactivated.';}else{$error='The user could not be updated.';}}}}?>
<main class="admin-shell"><aside class="admin-sidebar" data-admin-sidebar><div class="admin-brand"><a class="brand" href="<?= e(app_url('index.php')) ?>"><span class="brand-mark"><i></i><i></i></span><span>2B2X</span></a></div><nav class="admin-nav"><a href="<?= e(app_url('admin/index.php')) ?>">Dashboard</a><a class="active" href="<?= e(app_url('admin/users.php')) ?>">Users</a><a href="<?= e(app_url('admin/releases.php')) ?>">Releases</a><a href="<?= e(app_url('admin/downloads.php')) ?>">Downloads</a><a href="<?= e(app_url('admin/changelog.php')) ?>">Changelog</a><a href="<?= e(app_url('admin/blog.php')) ?>">Blog</a><a href="<?= e(app_url('admin/support.php')) ?>">Support</a><a href="<?= e(app_url('admin/settings.php')) ?>">Settings</a></nav><div class="admin-sidebar-footer"><a class="button button-ghost button-small" href="<?= e(app_url('admin/logout.php')) ?>">Logout</a></div></aside><div class="admin-main"><header class="admin-topbar"><button class="menu-toggle" data-admin-toggle aria-label="Open admin menu"><span></span><span></span></button><div><h1>User management</h1><small style="color:var(--subtle)">Accounts and access control</small></div><span class="status-pill">Live data</span></header><div class="admin-content"><div class="admin-toolbar"><div><h2>All users</h2><p><?= count($users) ?> registered account<?= count($users)===1?'':'s' ?></p></div><div class="field"><input placeholder="Search users" data-search="users-table"></div></div><section class="admin-card admin-table-card"><div class="table-wrap"><table id="users-table"><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php if(!$users):?><tr><td colspan=6><div class="empty-state"><h3>No users found</h3><p>Register a user to populate this table.</p></div></td></tr><?php else:foreach($users as $user):?><tr><td><strong><?= e((string)$user['username']) ?></strong></td><td><?= e((string)$user['email']) ?></td><td><span class="status-badge <?= ($user['role']??'user')==='admin'?'status-active':'status-pending' ?>"><?= e((string)$user['role']) ?></span></td><td><span class="status-badge <?= !empty($user['active'])?'status-active':'status-closed' ?>"><?= !empty($user['active'])?'Active':'Inactive' ?></span></td><td><?= e(format_date((string)$user['created_at'])) ?></td><td><div class="admin-actions"><form method=post class=sr-only><input type=hidden name=csrf_token value="<?= e(csrf_token()) ?>"><input type=hidden name=id value="<?= e((string)$user['id']) ?>"><input type=hidden name=action value="<?= ($user['active']??true)?'deactivate':'activate' ?>"><button type=submit><?= ($user['active']??true)?'Deactivate':'Activate' ?></button></form><?php if(($user['role']??'')!=='admin'): ?><form method=post class=sr-only><input type=hidden name=csrf_token value="<?= e(csrf_token()) ?>"><input type=hidden name=id value="<?= e((string)$user['id']) ?>"><input type=hidden name=action value=delete><button type=button data-confirm="<?= e(app_url('admin/users.php?action=delete&id='.rawurlencode((string)$user['id']))) ?>">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach;endif; ?></tbody></table></div></section><?php if($error):?><div class="alert error" style="margin-top:18px"><?= e($error) ?></div><?php elseif($message):?><div class="alert success" style="margin-top:18px"><?= e($message) ?></div><?php endif; ?></div></div><div class="modal" data-modal aria-hidden=true><div class="modal-card"><h2>Delete user?</h2><p>This action removes the user's account and download history from the local data store.</p><form id="confirm-form" method=post><input type=hidden name=csrf_token value="<?= e(csrf_token()) ?>"><input type=hidden name=action value=delete><input type=hidden name=id value=""><div class="modal-actions"><button class="button button-ghost" type=button data-close-modal>Cancel</button><button class="button button-primary" type=submit>Delete user</button></div></form></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
